//! 目的上限制約付き修復を小規模JSONモデルで直接検証する入口。
use mip_codex::{model::Model,heuristic::Repair,objective_repair,solve::Result};
fn main(){let a:Vec<_>=std::env::args().collect();let m:Model=serde_json::from_reader(std::fs::File::open(&a[1]).unwrap()).unwrap();let seed=vec![1.;m.variables.len()];let lower:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let repair=Repair::new(&m);let end=std::time::Instant::now()+std::time::Duration::from_secs(1);let(x,stats)=objective_repair::improve(&m,&repair,&seed,&lower,&upper,end).unwrap();let result=Result{status:"feasible_objective_repair_kernel".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),root_objective_repair:Some(stats),..Result::default()};println!("{}",serde_json::to_string(&result).unwrap());}
